//! The Rust post-processing against `post.py` (`tests/fixtures/gen/`) on the
//! same solved fields of one run (`tests/fixtures/post/`, regenerated by
//! `gen-post.sh`): every intake band, the exhaust and return temperatures
//! within 0.05 °C, RCI-HI and RTI within 0.1 (percentage points), the
//! energy figure within 0.1 %.

use std::collections::BTreeMap;
use std::io::Read;
use std::path::PathBuf;

use portal_cfd::checks::{Opening, heat_removed};
use portal_cfd::input::CaseInput;
use portal_cfd::post::{self, Nearest};
use serde_json::Value;

fn path(rel: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/post")
        .join(rel)
}

fn json<T: serde::de::DeserializeOwned>(rel: &str) -> T {
    serde_json::from_slice(&std::fs::read(path(rel)).unwrap()).unwrap()
}

/// Cell centres (m), temperature (K) and velocity, as `post.py` read them.
fn cells() -> (Vec<[f64; 3]>, Vec<f64>, Vec<[f64; 3]>) {
    let mut raw = vec![];
    flate2::read::GzDecoder::new(&std::fs::read(path("cells.f32.gz")).unwrap()[..])
        .read_to_end(&mut raw)
        .unwrap();
    let n = u32::from_le_bytes(raw[..4].try_into().unwrap()) as usize;
    let f: Vec<f64> = raw[4..]
        .chunks_exact(4)
        .map(|b| f32::from_le_bytes(b.try_into().unwrap()) as f64)
        .collect();
    assert_eq!(f.len(), n * 7);
    let row = |i: usize| &f[i * 7..i * 7 + 7];
    (
        (0..n).map(|i| [row(i)[0], row(i)[1], row(i)[2]]).collect(),
        (0..n).map(|i| row(i)[3]).collect(),
        (0..n).map(|i| [row(i)[4], row(i)[5], row(i)[6]]).collect(),
    )
}

fn near(a: f64, b: f64, tol: f64, what: &str, errs: &mut Vec<String>) {
    println!("{what}: rust {a:.6}, post.py {b:.6}, diff {:+.2e}", a - b);
    if (a - b).abs() > tol {
        errs.push(format!("{what}: rust {a:.4}, post.py {b:.4}"));
    }
}

#[test]
fn post_processing_matches_post_py() {
    let input: CaseInput = json("input.json");
    let expected: Value = json("expected.json");
    let (centres, t_k, u) = cells();
    let t_c: Vec<f64> = t_k.iter().map(|t| t - 273.15).collect();
    let nearest = Nearest::for_case(&input, &centres);
    let grid = post::resample(&input, &nearest, &t_c, &u, post::H);
    let n = post::numbers_raw(&input, &grid, &t_c, &u, &[]);

    let mut errs = vec![];
    let x = |v: &Value| v.as_f64().unwrap();
    for (i, r) in n.racks.iter().enumerate() {
        let e = &expected["racks"][i];
        for (h, ours) in [
            ("top", r.intake.top.mean),
            ("mid", r.intake.mid.mean),
            ("bottom", r.intake.bottom.mean),
        ] {
            near(
                ours,
                x(&e["intake"][h]),
                0.05,
                &format!("rack {} {h}", i + 1),
                &mut errs,
            );
        }
        near(
            r.exhaust,
            x(&e["exhaust"]),
            0.05,
            &format!("rack {} exhaust", i + 1),
            &mut errs,
        );
    }
    near(
        n.return_temp,
        x(&expected["return_temp"]),
        0.05,
        "return",
        &mut errs,
    );
    near(n.rci_hi, x(&expected["rci_hi"]), 0.1, "RCI-HI", &mut errs);
    near(n.rti, x(&expected["rti"]), 0.1, "RTI", &mut errs);
    near(n.t_min, x(&expected["t_min"]), 0.05, "t_min", &mut errs);
    near(n.t_max, x(&expected["t_max"]), 0.05, "t_max", &mut errs);
    near(
        n.u_max,
        x(&expected["u_max"]),
        1e-3 * x(&expected["u_max"]),
        "u_max",
        &mut errs,
    );

    let openings: BTreeMap<String, BTreeMap<String, Vec<f64>>> = json("openings.json");
    let o: Vec<Opening> = openings
        .values()
        .map(|v| Opening {
            phi: v["phi"].clone(),
            t: v["t"].clone(),
        })
        .collect();
    let (removed, _) = heat_removed(&input, &o);
    let theirs = x(&expected["heat_removed_w"]);
    near(removed, theirs, 1e-3 * theirs, "heat removed", &mut errs);
    assert!(errs.is_empty(), "{}", errs.join("\n"));
}
